/** Lookup by the two-letter code used in `content/site.ts`. */
export const mapStateByCode: Record<string, MapStateShape> = Object.fromEntries(
  mapStates.map((s) => [s.code, s]),
)

// ── Regenerating ────────────────────────────────────────────────────────────
// If the artwork is redrawn, the six states have to be re-clustered. map.svg
// carries no ids or groups — the only thing that distinguishes the six is fill
// colour (#D6AC68 = North Carolina, #14294C = the five coming-soon states,
// #E5E5E5 = everything else) — so the split was done geometrically: fit d3-geo's
// albersUsa projection to the dot cloud, invert each dot back to a lon/lat, and
// point-in-polygon it against us-atlas state boundaries. Colour is treated as
// ground truth over geometry, so a dot sitting on a border can never land in the
// wrong bucket; geometry only decides which of the five navy states a navy dot
// belongs to.
